// Class 12 English - Vistas Chapter 5: On the Face of It (Susan Hill)
// Fully standardized to English Core Blueprint & AGENTS.md guidelines
// Theme Color: #AB47BC

export const c12EngV5HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Chapter Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(171, 71, 188, 0.22), rgba(142, 36, 170, 0.1)); border: 1.5px solid #AB47BC; border-radius: 12px; padding: 20px; margin-bottom: 25px; box-shadow: 0 4px 22px rgba(171, 71, 188, 0.15);\">\n    <div style=\"display: flex; align-items: center; gap: 10px; margin-bottom: 8px;\">\n      <span style=\"background: #AB47BC; color: #FFF; font-size: 12px; font-weight: 800; padding: 4px 10px; border-radius: 6px; letter-spacing: 0.5px;\">VISTAS &bull; CHAPTER 5</span>\n      <span style=\"color: #94A3B8; font-size: 13.5px; font-weight: 600;\">CLASS XII ENGLISH CORE (SUPPLEMENTARY READER)</span>\n    </div>\n    <h1 style=\"color: #FFFFFF; font-size: 26px; font-weight: 900; margin: 0 0 6px 0; letter-spacing: -0.5px;\">On the Face of It</h1>\n    <p style=\"color: #CBD5E1; font-size: 15px; margin: 0; font-style: italic;\">\n      By Susan Hill (b. 1942, UK) &mdash; Physical Disability, Psychological Alienation &amp; The Transformative Power of Empathy\n    </p>\n  </div>\n\n  <!-- Quick Glossary & Chapter Dossier Card -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border: 1.5px solid rgba(171, 71, 188, 0.4); border-radius: 10px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.35);\">\n    <h3 style=\"color: #AB47BC; font-size: 18px; margin: 0 0 12px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>📖</span> Quick Glossary &amp; Chapter Dossier: On the Face of It\n    </h3>\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; font-size: 14px; color: #CBD5E1;\">\n      <div><b style=\"color: #AB47BC;\">Author:</b> Susan Hill (Acclaimed English playwright and novelist)</div>\n      <div><b style=\"color: #AB47BC;\">Genre:</b> One-Act Psychological Play / Two-Character Drama</div>\n      <div><b style=\"color: #AB47BC;\">Setting:</b> Mr. Lamb's sprawling, welcoming garden with crab-apple trees</div>\n      <div><b style=\"color: #AB47BC;\">Protagonist:</b> Derry (Derek, 14-year-old boy with acid-burned face)</div>\n      <div><b style=\"color: #AB47BC;\">Mentor:</b> Mr. Lamb (Elderly amputee with a tin leg blown off in war)</div>\n      <div><b style=\"color: #AB47BC;\">Core Theme:</b> Psychological alienation vs. Bodily impairment; Overcoming cynicism</div>\n      <div><b style=\"color: #AB47BC;\">Key Parables:</b> The Weed &amp; Flower; The Timid Man Locked in a Room; Beauty &amp; The Beast</div>\n      <div><b style=\"color: #AB47BC;\">Climactic Motif:</b> Derry's redemption through return vs. Mr. Lamb's fatal fall</div>\n    </div>\n  </div>\n\n  <!-- Section 1: Executive Summary & Thematic Context -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 28px 0 16px 0;\">\n    1. Executive Summary &amp; Psychological Framework\n  </h2>\n  <p>\n    <b style=\"color: #AB47BC;\">'On the Face of It'</b>, written by celebrated British dramatist and novelist <b style=\"color: #AB47BC;\">Susan Hill</b>, is a poignant, deeply sensitive one-act play exploring the hidden psychological trauma, social alienation, and existential isolation experienced by physically challenged individuals.\n  </p>\n  <p>\n    The play centers upon an accidental encounter in a secluded garden between two people of vastly disparate generations who share the common bond of physical deformity: <b style=\"color: #AB47BC;\">Derry (Derek)</b>, an introverted, hypersensitive fourteen-year-old boy whose face is severely disfigured by acid, and <b style=\"color: #AB47BC;\">Mr. Lamb</b>, an elderly, warm-hearted man whose leg was blown off by a bomb during the war and replaced with an artificial tin limb. While Derry has retreated into an impenetrable shell of misanthropy, bitterness, and self-hatred due to cruel societal stares and superficial pity, Mr. Lamb has embraced life with boundless optimism, open gates, and unconditional love for nature. Through their poignant dialogue, Mr. Lamb gently dismantles Derry's defense mechanisms, teaching him that bodily disfigurement does not define the human soul, and inspiring the boy to reclaim his agency in the world.\n  </p>\n\n  <!-- Section 2: Chronological Narrative Architecture -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    2. Chronological &amp; Thematic Narrative Architecture\n  </h2>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(i) The Accidental Intrusion into the Garden</h3>\n  <p>\n    The play opens in Mr. Lamb's sunlit garden, filled with rustling leaves, birdsong, and crab-apple trees. Fourteen-year-old <b style=\"color: #AB47BC;\">Derry</b> enters the garden by climbing over the perimeter wall. He believes the grounds are abandoned and desires a secluded, uninhabited sanctuary where no human eyes can gaze upon him.\n  </p>\n  <p>\n    Startled, Derry is suddenly addressed by <b style=\"color: #AB47BC;\">Mr. Lamb</b>, who is sitting peacefully nearby: <i>\"Mind the apples! You might trip on the windfalls!\"</i> Panicked and defensive, Derry attempts to flee, stuttering that he did not intend to steal anything. Mr. Lamb reassures him with gentle warmth, explaining that the garden gate is always wide open and everyone is welcome.\n  </p>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(ii) Derry's Complex of Bitterness &amp; Social Alienation</h3>\n  <p>\n    Derry remains deeply mistrustful. He assumes Mr. Lamb is staring at his scarred cheek and reacting with horror. Derry explains that acid was spilled over one side of his face, burning the skin away and permanently destroying his appearance: <i>\"It ate my face up. It ate me up. And now it's like this and it won't ever be any different.\"</i>\n  </p>\n  <p>\n    Derry reveals the agonizing psychological wound caused by societal cruelty. People either look at him with undisguised terror, pretend not to notice with false sympathy, or whisper cruel remarks behind his back. He recalls hearing two women at a bus stop whispering about his face: <i>\"Look at that terrible thing! That's a face only a mother could love!\"</i> Derry believes nobody will ever kiss him or befriend him, concluding that everyone hates him.\n  </p>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(iii) Mr. Lamb's Philosophy: Weeds, Flowers &amp; The Tin Leg</h3>\n  <p>\n    Rather than offering superficial pity, Mr. Lamb challenges Derry's worldview through provocative metaphors. He reveals that one of his legs was blown off in the war years ago and replaced with an artificial <b style=\"color: #AB47BC;\">tin leg</b>. Local children mock him in the street, shouting <i>\"Lamey-Lamb!\"</i>, yet he takes no offense because the nickname fits his condition and the children still enter his garden for apples, pears, and toffee.\n  </p>\n  <p>\n    When Derry contrasts flowers with ugly weeds, Mr. Lamb asks: <i>\"Why is one green, growing thing called a weed and another a flower? It's all life &mdash; growing. Same as you and me.\"</i> He asserts that differences are purely arbitrary human prejudices; underneath physical exteriors, all living things share the same essential vitality.\n  </p>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(iv) The Parable of the Timid Man &amp; Beauty and the Beast</h3>\n  <p>\n    To cure Derry's self-imposed isolation, Mr. Lamb narrates the satirical parable of a timid man who locked himself inside his private bedroom because he was terrified of everything in the world&mdash;a bus might run him down, a man might breathe deadly germs on him, or a donkey might kick him to death. So he locked the door, climbed into bed, and stayed there. In the end, a heavy framed picture fell from the wall onto his head and killed him! Derry bursts into spontaneous laughter, appreciating the ironic truth that isolating oneself does not protect against mortality or suffering.\n  </p>\n  <p>\n    When Derry bitterly dismisses the fairy tale of <b style=\"color: #AB47BC;\">'Beauty and the Beast'</b>, noting that even if Beauty kissed the Beast he would never turn into a handsome prince in real life, Mr. Lamb gently reminds him that external beauty is fleeting, while inner character and self-acceptance endure forever.\n  </p>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(v) Open Curtains &amp; Listening to Bees Sing</h3>\n  <p>\n    Derry notices that Mr. Lamb's house has no curtains on the windows. Mr. Lamb explains: <i>\"I'm not fond of curtains. Shutting things out, shutting things in. I like the light and the darkness, and the windows open, to hear the wind.\"</i>\n  </p>\n  <p>\n    When Derry mentions that bees only buzz monotonously, Mr. Lamb disagrees, saying that if one listens patiently, bees <b style=\"color: #AB47BC;\">hum and sing</b>. Mr. Lamb shows Derry that he possesses two arms, two legs, eyes, ears, a tongue, and a brain; he has the power to achieve anything he desires in life, perhaps even surpass whole, able-bodied people, if he resolves his mind to it.\n  </p>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(vi) Derry's Awakening &amp; Confrontation with His Mother</h3>\n  <p>\n    For the first time in his life, Derry feels understood, valued, and respected. Shedding his defensive anger, he promises Mr. Lamb that he will run home, inform his mother where he is, and return to help Mr. Lamb harvest the crab apples to make jelly. Mr. Lamb smiles wistfully, remarking that people always promise to return but rarely do because the world pulls them back.\n  </p>\n  <p>\n    Derry rushes home to his mother. When he announces his intention to return to Mr. Lamb's garden, his mother forbids him, repeating neighborhood gossip that the old man is eccentric, peculiar, and untrustworthy. Derry fiercely defies her prejudices, asserting that Mr. Lamb talks of things that truly matter&mdash;things nobody else talks about&mdash;and sprints back across the fields to the garden.\n  </p>\n\n  <h3 style=\"color: #AB47BC; font-size: 17px; margin-top: 22px;\">(vii) The Tragic Climax &amp; Spiritual Transformation</h3>\n  <p>\n    Panting and breathless, Derry reaches the garden, shouting in triumphant joy: <i>\"I came back, Lamey-Lamb! I did come back!\"</i>\n  </p>\n  <p>\n    However, a terrible sight greets him. A ladder has slipped against an apple tree, and Mr. Lamb lies motionless upon the grass with a basket of apples overturned nearby. Derry kneels beside the fallen mentor, shaking him in desperate panic: <i>\"Mr. Lamb! It's Derry! I came back!\"</i> Receiving no response, Derry realizes the old man is dead. As tears stream down his face, Derry weeps bitterly. Yet, although Mr. Lamb has died, his philosophy has permanently resurrected Derry's soul: Derry will never retreat into darkness or fear his burned face again.\n  </p>\n\n  <!-- Section 3: Psychological Character Profiles -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    3. Psychological Character Sketches &amp; Profiles\n  </h2>\n\n  <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 16px; margin-bottom: 25px;\">\n    \n    <!-- Derry -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 8px 0;\">1. Derry (The Wounded Introvert)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A fourteen-year-old boy suffering from acute inferiority complex and defensive cynicism due to an acid-burned face. He equates his physical scar with total unworthiness. Through Mr. Lamb's patient wisdom, Derry undergoes a profound psychological metamorphosis, casting aside his victim mentality, defying maternal overprotection, and embracing life with courage.\n      </p>\n    </div>\n\n    <!-- Mr. Lamb -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 8px 0;\">2. Mr. Lamb (The Resilient Philanthropist)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        An elderly amputee living alone with an artificial tin leg. Despite experiencing war trauma and loneliness, he refuses self-pity. He keeps his garden gate wide open, welcoming children and strangers alike. With unshakeable optimism and poetic wisdom, he acts as a spiritual healer for Derry, leaving a legacy of hope and inner freedom.\n      </p>\n    </div>\n\n    <!-- Derry's Mother -->\n    <div style=\"background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px;\">\n      <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 8px 0;\">3. Derry's Mother (The Overprotective Parent)</h3>\n      <p style=\"font-size: 14px; margin: 0; color: #CBD5E1;\">\n        A protective yet unconsciously suffocating parent. Driven by anxiety and societal prejudice, she inadvertently exacerbates Derry's isolation by babying him and only kissing the unburned side of his face. Her fear of neighborhood gossip regarding Mr. Lamb highlights the conventional societal prejudices Derry must overcome.\n      </p>\n    </div>\n\n  </div>\n\n  <!-- Section 4: Literary & Rhetorical Devices Master Table -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    4. Literary &amp; Rhetorical Devices Master Table\n  </h2>\n  <div style=\"overflow-x: auto; margin-bottom: 25px;\">\n    <table style=\"width: 100%; border-collapse: collapse; font-size: 14.5px; text-align: left; background: rgba(15, 23, 42, 0.9); border-radius: 8px; overflow: hidden;\">\n      <thead>\n        <tr style=\"background: rgba(171, 71, 188, 0.25); color: #FFFFFF; border-bottom: 2px solid #AB47BC;\">\n          <th style=\"padding: 12px 14px;\">Literary Device</th>\n          <th style=\"padding: 12px 14px;\">Textual Quote / Example</th>\n          <th style=\"padding: 12px 14px;\">Literary &amp; Thematic Effect</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #AB47BC;\">Allegorical Parable</td>\n          <td style=\"padding: 12px 14px;\">The Weed and Flower metaphor; the man who locked himself in his room to avoid death.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Conveys profound philosophical truths regarding arbitrary social prejudices and the absurdity of self-imposed isolation.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #AB47BC;\">Symbolism</td>\n          <td style=\"padding: 12px 14px;\">The Open Gate, Absence of Curtains, Humming Bees, and the Apple Garden.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Symbolizes openness, vulnerability, mental freedom, and active engagement with the living universe.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #AB47BC;\">Dramatic Contrast</td>\n          <td style=\"padding: 12px 14px;\">Derry's youthful bitterness and retreat vs. Mr. Lamb's aged resilience and open-hearted engagement.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Illustrates that mental attitude, not physical impairment, determines whether a person lives in misery or joy.</td>\n        </tr>\n        <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.08);\">\n          <td style=\"padding: 12px 14px; font-weight: bold; color: #AB47BC;\">Tragic Irony</td>\n          <td style=\"padding: 12px 14px;\">Mr. Lamb falls from his ladder and dies just as Derry returns, proving the boy was true to his word.</td>\n          <td style=\"padding: 12px 14px; color: #CBD5E1;\">Heightens emotional pathos while confirming Derry's spiritual redemption and independence.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <!-- Section 5: Board Exam Strategy & High-Scoring Tips Box -->\n  <div style=\"background: rgba(15, 23, 42, 0.92); border-left: 5px solid #AB47BC; border-radius: 8px; padding: 18px 20px; margin-bottom: 25px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 18px; margin: 0 0 10px 0; display: flex; align-items: center; gap: 8px;\">\n      <span>🎯</span> Board Examination Master Tips: Scoring 100% in On the Face of It\n    </h3>\n    <ul style=\"color: #CBD5E1; font-size: 14.5px; padding-left: 20px; margin: 0; line-height: 1.8;\">\n      <li><b style=\"color: #AB47BC;\">Analyze Both Disabilities:</b> Clearly contrast Derry's <b style=\"color: #AB47BC;\">visible burned face</b> with Mr. Lamb's <b style=\"color: #AB47BC;\">hidden tin leg</b> and their opposite psychological reactions.</li>\n      <li><b style=\"color: #AB47BC;\">Reference Key Parables:</b> Always quote the parable of the <b style=\"color: #AB47BC;\">man who locked himself in his room</b> and the <b style=\"color: #AB47BC;\">weed and flower</b> distinction.</li>\n      <li><b style=\"color: #AB47BC;\">Highlight the Ending:</b> Emphasize that although Mr. Lamb dies, Derry's transformation is permanent; he has outgrown his bitterness and will never hide from life again.</li>\n    </ul>\n  </div>\n\n</div>\n";

export const c12EngV5HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; line-height: 1.8; color: #E2E8F0; max-width: 950px; margin: 0 auto; padding: 12px; font-size: 15.5px;\">\n\n  <!-- Section Header Badge -->\n  <div style=\"background: linear-gradient(135deg, rgba(171, 71, 188, 0.22), rgba(142, 36, 170, 0.1)); border-left: 5px solid #AB47BC; padding: 16px 20px; border-radius: 8px; margin-bottom: 25px;\">\n    <h2 style=\"color: #AB47BC; font-weight: 900; margin: 0 0 4px 0; font-size: 21px;\">\n      BOARD EXAMINATION QUESTIONS &amp; MODEL ANSWERS\n    </h2>\n    <span style=\"color: #94A3B8; font-size: 14px; font-weight: 600;\">Standardized to CBSE &amp; JKBOSE Class XII English Core Blueprint &bull; Theme Color Standardized</span>\n  </div>\n\n  <!-- SECTION A: EXTRACT-BASED QUESTIONS -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 26px 0 16px 0;\">\n    SECTION A: Extract-Based Objective Questions (1 Mark Each)\n  </h2>\n\n  <!-- Extract 1 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #AB47BC;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #AB47BC;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"MR LAMB: Mind the apples! You might trip on the windfalls and break your neck.<br/>\n      DERRY: I... there's somebody here... I thought it was... empty... an empty house.<br/>\n      MR LAMB: So it is. Since I'm out here in the garden. It is empty. Until I go back inside. In the meantime, I'm out here. Mind the apples.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q1: How did Derry enter Mr. Lamb's garden?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry climbed over the <b style=\"color: #AB47BC;\">garden wall</b> instead of walking in through the open gate.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q2: Why did Derry enter the garden secretly?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> He believed the house and grounds were deserted, seeking a solitary refuge away from human eyes.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q3: What warning does Mr. Lamb give to the startled boy?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> To mind the crab apples that had fallen on the grass (<b style=\"color: #AB47BC;\">windfalls</b>) lest he trip and fall.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q4: What tone does Mr. Lamb adopt toward the intruder?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> A welcoming, gentle, and unbothered tone, instantly putting the boy at ease.\n    </p>\n  </div>\n\n  <!-- Extract 2 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #AB47BC;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #AB47BC;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"It got into my face and ate me up. It ate my face up. It ate me up. And now it's like this and it won't ever be any different.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q5: What substance is Derry referring to as 'it'?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> <b style=\"color: #AB47BC;\">Acid</b> that splashed onto one side of his face and burned away his skin.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q6: What psychological trauma did this event inflict on Derry?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> It destroyed his self-worth, making him feel that his entire identity and soul were devoured by deformity.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q7: What outlook toward the future does Derry express in this line?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Total despair and hopelessness, believing his life and appearance can never change or improve.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q8: How old was Derry at the time of this conversation?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry was <b style=\"color: #AB47BC;\">fourteen years old</b>.\n    </p>\n  </div>\n\n  <!-- Extract 3 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #AB47BC;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #AB47BC;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"There was a man who locked himself up in his room because he was afraid. He was afraid of everything in the world. A bus might run him over, or a man might breathe deadly germs on him, or a donkey might kick him to death... So he went into his room, and locked the door, and got into his bed, and stayed there.\"\n    </p>\n    \n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q9: Why does Mr. Lamb narrate this parable to Derry?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> To highlight the absurdity and futility of isolating oneself from the world out of fear.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q10: What ultimately happened to the man locked inside the room?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> A picture fell off the wall onto his head and killed him instantly.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q11: How did Derry react upon hearing the conclusion of this story?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry burst into spontaneous laughter, appreciating the ironic humor and philosophical truth.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q12: What core lesson does the parable convey regarding human existence?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Life cannot be lived in fearful retreat; one must actively participate in the living world.\n    </p>\n  </div>\n\n  <!-- Extract 4 -->\n  <div style=\"background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.3); border-radius: 8px; padding: 16px; margin-bottom: 20px; border-left: 4px solid #AB47BC;\">\n    <p style=\"color: #94A3B8; font-style: italic; margin-top: 0; line-height: 1.7;\">\n      <b style=\"color: #AB47BC;\">Read the extract given below and answer the questions that follow:</b><br/>\n      \"I came back, Lamey-Lamb. I did come back! You said I wouldn't, but I did! Look, I'm here! Mr. Lamb! Mr. Lamb! You've... oh, no, no, no!\"\n    </p>\n    \n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q13: Why had Mr. Lamb doubted that Derry would return?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Past experience taught him that people constantly promise to return, but societal pressure stops them.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q14: What tragedy has occurred in the garden when Derry arrives?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Mr. Lamb fell from his ladder while picking apples and lies dead upon the grass.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q15: What does Derry's emotional cry reveal about his transformation?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> He had completely overcome his cynicism and formed a profound emotional bond with Mr. Lamb.\n    </p>\n\n    <p>\n      <b style=\"color: #AB47BC; font-size: 15px;\">Q16: Did Derry successfully keep his promise despite his mother's resistance?</b><br/>\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Yes, he boldly defied his mother and sprinted miles across the fields to return.\n    </p>\n  </div>\n\n  <!-- SECTION B: SHORT ANSWER QUESTIONS -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION B: Short Answer Questions (3 Marks Each | 40&ndash;50 Words)\n  </h2>\n\n  <!-- Q17 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q17: Why did Derry enter Mr. Lamb's garden by climbing over the wall?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry climbed over the wall because he thought the garden was deserted. Suffering from severe self-consciousness about his acid-burned face, he was looking for a secluded spot where no one would stare at him or pass hurtful comments.\n    </p>\n  </div>\n\n  <!-- Q18 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q18: How does Mr. Lamb explain the distinction between a weed and a flower?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Mr. Lamb points out that both weeds and flowers are green, growing living things. The label 'weed' or 'flower' is an arbitrary human prejudice. In nature's eyes, all living organisms share equal vitality, just as all human beings possess equal intrinsic worth.\n    </p>\n  </div>\n\n  <!-- Q19 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q19: How did Mr. Lamb lose his leg, and how does he handle neighborhood mockery?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Mr. Lamb lost his leg during the war when a bomb blew it off. Local street children call him <b style=\"color: #AB47BC;\">\"Lamey-Lamb\"</b>, but he never takes offense, cheerfully acknowledging that it fits his physical reality while welcoming them into his garden for apples and toffee.\n    </p>\n  </div>\n\n  <!-- Q20 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q20: What hurtful remark did Derry overhear women making at the bus stop?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> While waiting at a bus stop, Derry overheard two women whispering: <i>\"Look at that terrible thing! That's a face only a mother could love!\"</i> This cruel comment deeply scarred his adolescent psychology, convincing him that the outside world would only ever reject him.\n    </p>\n  </div>\n\n  <!-- Q21 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q21: Why does Mr. Lamb dislike curtains in his house?</h4>\n    <p style=\"margin: 0; color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Mr. Lamb dislikes curtains because they shut things out and shut things in. He loves welcoming natural sunlight and darkness into his home, keeping the windows open so he can listen to the breeze and remain connected with the living world outside.\n    </p>\n  </div>\n\n  <!-- Q22 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q22: How does Mr. Lamb view the sound made by bees?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> While Derry claims that bees merely make an annoying buzzing noise, Mr. Lamb explains that if one listens attentively and patiently, bees <b style=\"color: #AB47BC;\">hum and sing</b>. Perception is entirely a matter of attitude and positive attention.\n    </p>\n  </div>\n\n  <!-- Q23 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q23: What does Derry think about the fairy tale 'Beauty and the Beast'?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry cynically rejects the fairy tale, arguing that real life is not like stories. Even if someone kissed him, his acid-burned skin would never transform into handsome features, insisting he will stay a monster forever.\n    </p>\n  </div>\n\n  <!-- Q24 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q24: How does Mr. Lamb inspire Derry about his physical capabilities?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Mr. Lamb reminds Derry that he possesses two arms, two legs, eyes, ears, a tongue, and a working brain. With determination, he can master life and even achieve far greater things than people with undamaged bodies.\n    </p>\n  </div>\n\n  <!-- Q25 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q25: Why did Derry's mother forbid him from returning to Mr. Lamb's garden?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry's mother was swayed by local neighborhood gossip and prejudice. She believed Mr. Lamb was eccentric, suspicious, and untrustworthy, fearing that the elderly man would fill Derry's head with unhealthy ideas.\n    </p>\n  </div>\n\n  <!-- Q26 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q26: How did Derry react when his mother attempted to stop him?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry firmly defied his mother, declaring that Mr. Lamb talked about things that truly mattered&mdash;things nobody else ever said. He warned that if he did not go back now, he would never go anywhere in the world again.\n    </p>\n  </div>\n\n  <!-- Q27 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q27: What fatal accident occurred to Mr. Lamb at the conclusion of the play?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> While using a ladder to harvest crab apples from the tree with a stick, the ladder slipped on the grass. Mr. Lamb fell heavily backward with a crash and died on the spot.\n    </p>\n  </div>\n\n  <!-- Q28 -->\n  <div style=\"margin-bottom: 20px; background: rgba(15, 23, 42, 0.65); padding: 14px 16px; border-radius: 8px; border-left: 4px solid #AB47BC;\">\n    <h4 style=\"color: #AB47BC; font-size: 16px; margin: 0 0 8px 0; font-weight: 700;\">Q28: Why does Derry weep beside Mr. Lamb's body?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry weeps out of devastating grief for the only person who accepted him unconditionally without pity or revulsion. Yet, his tears also signify his emotional rebirth; he has broken out of his emotional prison forever.\n    </p>\n  </div>\n\n  <!-- SECTION C: LONG ANSWER QUESTIONS -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION C: Long Answer / Thematic Questions (6 Marks Each | 120&ndash;150 Words)\n  </h2>\n\n  <!-- Q29 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q29: How does Mr. Lamb's optimistic attitude contrast with Derry's bitter cynicism in 'On the Face of It'?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #AB47BC;\">Model Answer:</b><br/>\n      <b>1. Introduction:</b> In Susan Hill's 'On the Face of It', both Derry and Mr. Lamb suffer from severe physical impairments, yet their psychological responses to their conditions represent diametrically opposed outlooks on life.<br/><br/>\n      <b>2. Derry's Negative Retreat:</b> Fourteen-year-old Derry, whose face is severely burned by acid, has retreated into a bitter shell of misanthropy and self-loathing. He interprets every look as horror and every comforting word as mockery. Tormented by cruel remarks like <i>\"a face only a mother could love\"</i>, Derry believes his disfigurement permanently excludes him from human affection.<br/><br/>\n      <b>3. Mr. Lamb's Positive Acceptance:</b> In contrast, Mr. Lamb, who lost his leg in the war, embraces life with radiant optimism. He leaves his garden gate wide open, refuses curtains on his windows, and finds music in the humming of bees. He views weeds and flowers as equals in nature's eyes and takes no offense when children call him 'Lamey-Lamb'. By demonstrating that mental attitude matters more than bodily form, Mr. Lamb teaches Derry that the real handicap lies in the mind, not in the body.\n    </p>\n  </div>\n\n  <!-- Q30 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q30: Analyze the pedagogical and psychological significance of the parables used by Mr. Lamb to guide Derry.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #AB47BC;\">Model Answer:</b><br/>\n      <b>1. The Power of Parables:</b> Rather than delivering dry moral lectures or offering patronizing sympathy, Mr. Lamb utilizes brilliant, memorable parables to gently penetrate Derry's hardened psychological defenses.<br/><br/>\n      <b>2. The Weed &amp; Flower and Timid Man:</b> The weed and flower analogy challenges Derry's rigid categorizations, showing that society's definitions of beauty and ugliness are arbitrary human prejudices. Next, the parable of the timid man who locked himself inside his bedroom out of fear of disease and accidents&mdash;only to be killed by a falling picture&mdash;exposes the futility of isolation. Through laughter, Derry realizes that retreating into solitude cannot protect him from pain.<br/><br/>\n      <b>3. The Humming Bees:</b> Finally, showing Derry that bees do not just buzz monotonously but hum and sing proves that reality depends on subjective perception. These parables dissolve Derry's victim mentality, awakening his desire to engage actively with the world.\n    </p>\n  </div>\n\n  <!-- Q31 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q31: Discuss the role of Derry's mother in shaping his alienated worldview.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #AB47BC;\">Model Answer:</b><br/>\n      <b>1. Maternal Overprotection:</b> Derry's mother represents the conventional, overprotective parent whose well-intentioned pity inadvertently worsens her disabled child's psychological trauma.<br/><br/>\n      <b>2. Reinforcing Rejection:</b> Derry reveals that his mother kisses him only on the unburned side of his face, an act of selective affection that reinforces his feeling of bodily revulsion. Her excessive sheltering prevents Derry from developing resilience. Furthermore, when Derry expresses enthusiasm about Mr. Lamb, his mother instantly forbids him from returning, parroting biased neighborhood gossip and warning him against the eccentric old man.<br/><br/>\n      <b>3. Breaking Free:</b> Her reaction exemplifies the societal prejudice and narrow-mindedness that Derry must overcome. By defying his mother's command and running back to Mr. Lamb's garden, Derry takes his first decisive step toward emotional maturity and spiritual independence.\n    </p>\n  </div>\n\n  <!-- Q32 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q32: Explain the symbolism of the garden, the open gates, and the lack of curtains in Mr. Lamb's house.\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #AB47BC;\">Model Answer:</b><br/>\n      <b>1. The Garden as Edenic Sanctuary:</b> Mr. Lamb's sprawling apple garden functions as an Edenic sanctuary of uninhibited nature, where weeds and flowers thrive side by side, symbolizing unconditional acceptance and equality.<br/><br/>\n      <b>2. The Open Gates:</b> The garden gate, which is never locked, symbolizes Mr. Lamb's hospitable heart and openness to the world. It welcomes strangers, outcasts, and neighborhood children alike, inviting all to share his apples and companionship.<br/><br/>\n      <b>3. The Absence of Curtains:</b> The complete lack of curtains in Mr. Lamb's house represents transparency and mental liberation. Curtains symbolize human desire to shut reality out and conceal vulnerabilities. By rejecting curtains, Mr. Lamb welcomes both light and darkness, birdsong and wind, embodying a soul completely free from pretense, shame, and fear.\n    </p>\n  </div>\n\n  <!-- Q33 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q33: How does the ending of the play blend tragedy with spiritual victory?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #AB47BC;\">Model Answer:</b><br/>\n      <b>1. The Climax &amp; Tragic Loss:</b> The conclusion of 'On the Face of It' is emotionally heartbreaking. Derry returns breathless to the garden to prove that he kept his promise, only to find Mr. Lamb lying dead upon the grass beside his fallen ladder.<br/><br/>\n      <b>2. Derry's Emotional Rebirth:</b> Despite the tragedy, the ending represents a triumphant spiritual victory. Derry's return marks the total demolition of his cynicism. When he knelt beside Mr. Lamb weeping, his tears were not tears of self-pity for his burned face, but tears of genuine love for another human being.<br/><br/>\n      <b>3. Enduring Legacy:</b> Mr. Lamb dies, but his spirit lives on inside Derry. Derry has learned that he has the agency to conquer life, and he will never retreat into darkness or fear human eyes again. The mentor perished, but the disciple was reborn.\n    </p>\n  </div>\n\n  <!-- Q34 -->\n  <div style=\"margin-bottom: 22px; background: rgba(15, 23, 42, 0.85); border: 1.5px solid rgba(171, 71, 188, 0.35); border-radius: 10px; padding: 18px; box-shadow: 0 4px 20px rgba(0,0,0,0.3);\">\n    <h3 style=\"color: #AB47BC; font-size: 17px; margin: 0 0 10px 0; font-weight: 800;\">\n      Q34: What message does Susan Hill convey regarding societal attitudes towards disabled individuals?\n    </h3>\n    <p style=\"color: #CBD5E1; line-height: 1.8; margin: 0;\">\n      <b style=\"color: #AB47BC;\">Model Answer:</b><br/>\n      <b>1. The Cruelty of Social Pity:</b> Susan Hill delivers a powerful critique of societal insensitivity toward disabled individuals. The play reveals that people with physical impairments suffer far more from societal stares, cruel whispers, and patronizing pity than from their actual physical injuries.<br/><br/>\n      <b>2. Superficial Judgments:</b> Society judges individuals purely 'on the face of it'&mdash;based on outward appearance&mdash;ignoring the living soul within. Derry is treated as a monster, while Mr. Lamb is ridiculed as a freak. This callousness drives disabled people into defensive isolation and misanthropy.<br/><br/>\n      <b>3. The True Remedy:</b> Hill demonstrates that the true remedy is neither patronizing sympathy nor superstitious avoidance, but unconditional acceptance, equal opportunity, and dignified friendship. Mr. Lamb treats Derry as a complete human being with immense potential, showing that empathy is the only force capable of healing broken souls.\n    </p>\n  </div>\n\n  <!-- SECTION D: NCERT TEXTBOOK EXERCISES -->\n  <h2 style=\"color: #AB47BC; font-size: 20px; font-weight: 800; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin: 30px 0 16px 0;\">\n    SECTION D: NCERT Textbook Exercises (Reading With Insight)\n  </h2>\n\n  <!-- NCERT Q1 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #AB47BC; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #AB47BC; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q35 (NCERT 1): What is it that draws Derry towards Mr Lamb in spite of himself?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry is drawn toward Mr. Lamb because Mr. Lamb is the first person who does not look at his acid-burned face with horror, repulsion, or superficial pity. Instead, Mr. Lamb talks to him as an equal, listens attentively, and challenges his bitterness with stimulating parables like the weed and flower. Mr. Lamb's open-hearted warmth, lack of curtains, and positive philosophy provide Derry with a safe sanctuary where he feels genuinely valued for the first time.\n    </p>\n  </div>\n\n  <!-- NCERT Q2 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #AB47BC; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #AB47BC; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q36 (NCERT 2): In which section of the play does Derry’s attitude towards Mr Lamb change? What brings about this change?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry's attitude transforms during the middle section of the play when Mr. Lamb reveals his own tin leg and shares the parable of the man who locked himself in his room. Hearing the old man laugh at neighborhood children calling him 'Lamey-Lamb' and witnessing his love for sunlight and singing bees shatters Derry's defensive cynicism. Realizing that Mr. Lamb treats him with respect rather than pity, Derry's hostility dissolves into trust and admiration.\n    </p>\n  </div>\n\n  <!-- NCERT Q3 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #AB47BC; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #AB47BC; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q37 (NCERT 3): What is the bond that unites the two—the old man, Mr Lamb, and the young boy, Derry?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> The primary bond uniting Derry and Mr. Lamb is their shared experience of physical impairment and the resulting social alienation. Both have endured the painful stares, thoughtless mockery, and isolation inflicted by an insensitive world. However, their deeper bond is emotional: Mr. Lamb suffers from chronic loneliness and craves genuine human company, while Derry desperately craves acceptance without judgment. In each other, they find the companion they had longed for.\n    </p>\n  </div>\n\n  <!-- NCERT Q4 -->\n  <div style=\"margin-bottom: 18px; background: rgba(15, 23, 42, 0.55); border-left: 4px solid #AB47BC; padding: 14px 16px; border-radius: 6px;\">\n    <h4 style=\"color: #AB47BC; font-size: 15.5px; margin: 0 0 6px 0; font-weight: 700;\">Q38 (NCERT 4): What is it that Derry’s mother fears? What advice does she give to Derry about Mr Lamb?</h4>\n    <p style=\"margin: 0; color: #CBD5E1; line-height: 1.75;\">\n      <span style=\"color: #AB47BC; font-weight: bold;\">✓ Answer:</span> Derry's mother fears that Mr. Lamb is eccentric, dangerous, and mentally unbalanced, having absorbed biased neighborhood gossip. She warns Derry that they have only lived in the area for three months, but she has heard terrible rumors about the old man. She strictly orders Derry not to return to the garden, advising him to stay home where he belongs, illustrating the suffocating parental overprotection that isolates disabled youth.\n    </p>\n  </div>\n\n</div>\n";

